python3 -I -c "
import json, re
def extract_solution(solution_str, method='strict'):
    if len(solution_str) > 300:
        solution_str = solution_str[-300:]
    solutions = re.findall(r'#### (\-?[0-9\.\,]+)', solution_str)
    if len(solutions) == 0: return None
    return solutions[-1].replace(',', '').replace('$', '')

for step in [0, 50, 100]:
    path = '/user/user1/harbor-runs/84186529d794/workspace/results/run100/val_generations/{}.jsonl'.format(step)
    disagree = []; n = 0; pred_one = 0
    for line in open(path):
        r = json.loads(line); n += 1
        ans = extract_solution(r['output'])
        exp = 1.0 if (ans is not None and ans == str(r['gts'][0])) else 0.0
        if exp == 1.0: pred_one += 1
